import{_ as t,o,c as a,a5 as s}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"FR 3.8.9 — Publish Facebook Story","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/07-publishing-social/3-8-9-publish-facebook-story/spec.md","filePath":"feature/srs/07-publishing-social/3-8-9-publish-facebook-story/spec.md"}'),r={name:"feature/srs/07-publishing-social/3-8-9-publish-facebook-story/spec.md"};function i(n,e,d,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-8-9-—-publish-facebook-story" tabindex="-1">FR 3.8.9 — Publish Facebook Story <a class="header-anchor" href="#fr-3-8-9-—-publish-facebook-story" aria-label="Permalink to &quot;FR 3.8.9 — Publish Facebook Story&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.8.9</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-115</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Publish Facebook Story</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Publishing &amp; Social (<code>3.8</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20, BR-57, BR-59</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01, MSG02, MSG03, MSG07, MSG45</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Publish vertical (<code>9:16</code>) ephemeral 24-hour Photo Stories or Video Stories (<code>&lt;= 60s</code>) to a connected <strong>Facebook Page</strong> via <code>FacebookPublishServiceImpl</code> using Meta Graph API <code>v19.0</code> Page Stories endpoints (<code>/{pageId}/photo_stories</code> and <code>/{pageId}/video_stories</code>).</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized member holding <code>Owner, Manager, Creator</code> in a Workspace, I want to execute <strong>Publish Facebook Story</strong> reliably across BrandHub&#39;s supported social publishing pipeline (<strong>Facebook, Instagram, TikTok, Threads</strong>) so that approved brand content is delivered, previewed, scheduled, and audited safely with full tenant isolation (<code>BR-20, BR-57, BR-59</code>).</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Canonical Role &amp; Workspace Scope (<code>BR-20</code>):</strong> Only authenticated Workspace members with role in <code>Owner, Manager, Creator</code> may invoke the public REST endpoints for <code>Publish Facebook Story</code>; unauthorized roles or cross-workspace requests fail deterministically with <code>403 FORBIDDEN</code> (<code>MSG07</code>).</li><li><strong>Four-Platform Scope Discipline:</strong> Strictly supports <strong>Facebook</strong>, <strong>Instagram</strong>, <strong>TikTok</strong>, and <strong>Threads</strong> — legacy/de-scoped platforms (such as Zalo OA or LinkedIn) are rejected at validation boundaries (<code>MSG02</code>).</li><li><strong>Production Pipeline &amp; Idempotency:</strong></li></ol><ul><li><strong>1. Story Media Pre-Validation:</strong> Enforces exactly <code>1</code> media item per Story job: JPEG/PNG (<code>&lt;= 10 MB</code>) for Photo Story, or H.264/AAC MP4 (<code>9:16</code>, <code>3s–60s</code>) for Video Story.</li><li><strong>2. Two-Phase Video Story Upload:</strong> For video stories, <code>FacebookPublishServiceImpl</code> initializes <code>POST /{pageId}/video_stories</code> (<code>upload_phase=start</code>) to obtain <code>video_id</code> and <code>upload_url</code>, streams/transfers the S3 presigned media, polls processing readiness, and finalizes with <code>upload_phase=finish</code>.</li></ul><ol start="4"><li><strong>Token &amp; Credential Security:</strong> Raw OAuth access/refresh tokens are encrypted at rest via AES-256-GCM (<code>CryptoUtils</code>) and never returned in client-facing <code>ApiResponse&lt;T&gt;</code> DTOs or written to application logs.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> All buttons, platform badges, status pills, validation alerts, and modal copy use synchronized key-parallel entries (<code>editor.publish.facebookStory.*</code>, <code>editor.placement.story</code> in <code>vi.json</code> &amp; <code>en.json</code>) on <code>brandhub-web</code> and <code>tr()</code> on <code>brandhub-mobile-app</code> — zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces (<code>pages/editor/index.tsx</code> (Placement = <code>Story</code>), <code>PhoneFrame.tsx</code>, <code>FacebookMockup.tsx</code> on Web and <code>src/screens/content/PostDetailScreen.tsx</code>, <code>src/screens/content-writing/SocialPreview.tsx</code> on Mobile) use semantic CSS variables / Tailwind <code>dark:</code> variants and <code>useAppPreferences().palette</code> tokens with WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/editor/index.tsx</code> (Placement = <code>Story</code>), <code>PhoneFrame.tsx</code>, <code>FacebookMockup.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/content/PostDetailScreen.tsx</code>, <code>src/screens/content-writing/SocialPreview.tsx</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / In-Flight:</strong> Skeleton placeholders on read views; spinner + disabled action button on mutations to prevent duplicate submissions.</li><li><strong>Empty:</strong> Contextual guidance card (e.g., prompt to connect social account via FR 3.8.1 or create/schedule a post via FR 3.8.6) with localized CTA.</li><li><strong>Success:</strong> Immediate <code>TanStack Query</code> cache invalidation, live status badge update, and localized toast notification.</li><li><strong>Error / Retryable Failure:</strong> Structured inline banner displaying localized error reason mapped from <code>MSG01, MSG02, MSG03, MSG07, MSG45</code> without losing draft edits.</li></ul></li></ul><h2 id="_5-api-messaging-contract" tabindex="-1">5. API &amp; Messaging Contract <a class="header-anchor" href="#_5-api-messaging-contract" aria-label="Permalink to &quot;5. API &amp; Messaging Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Endpoint / Upstream Route</th><th style="text-align:left;">Auth / Security</th><th style="text-align:left;">Controller / Service Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST /api/v1/workspaces/{workspaceId}/posts/{postId}/publish</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>PostController.publish()</code> -&gt; validates single vertical image/video &amp; dispatches <code>PublishJobMessage</code> (<code>platform=FACEBOOK</code>, <code>placement=STORY</code>)</td></tr><tr><td style="text-align:left;">`POST <a href="https://graph.facebook.com/v19.0/%7BpageId%7D/photo_stories" target="_blank" rel="noreferrer">https://graph.facebook.com/v19.0/{pageId}/photo_stories</a></td><td style="text-align:left;">/video_stories`</td><td style="text-align:left;">Decrypted Page Access Token</td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>INVALID_STORY_MEDIA</code> (<code>400</code>, <code>MSG02</code>): Missing media (text-only Story unsupported via Graph API), multiple attachments, or duration <code>&gt; 60s</code>.</li><li><code>FB_STORY_UPLOAD_FAILED</code> (<code>502/503</code>, <code>MSG45</code>): Upload session interrupted -&gt; retried safely via <code>publisher.retry.exchange</code>.</li><li><strong>Duplicate Delivery / Network Retry:</strong> <code>PublishJobConsumer</code> enforces Redis lock <code>processingPostIds:{postId}:{platform}</code> (<code>30m</code> TTL) and <code>DefaultClassMapper</code> cross-service <code>PublishJobMessage</code> compatibility so broker redeliveries never double-post to a Client&#39;s live social feed.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Domain Index &amp; Sibling FRs:</strong> <a href="./../README.html">3.8 Publishing &amp; Social Index</a> · <a href="./../3-8-1-connect-social-account/spec.html">FR 3.8.1 — Connect Social Account</a> · <a href="./../3-8-7-track-post-status/spec.html">FR 3.8.7 — Track Post Status</a></li><li><strong>Consolidated Extension Module:</strong> <a href="./../../../modules/07-billing-publisher-and-observability/social-publisher-resilience/spec.html"><code>social-publisher-resilience</code></a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/07-publishing-social.html">BA 3.8 Publishing &amp; Social</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Verified across <code>brandhub-business-service</code> and <code>brandhub-publisher-service</code> JUnit suites, RabbitMQ + Redis lock integration checks, Web &amp; Mobile UI integration, <code>vi.json</code>/<code>en.json</code> parity, and Light/Dark mode verification (<a href="./test.html">test.md</a>).</li><li><strong>Out of Scope:</strong> De-scoped platforms (Zalo OA), livestream broadcasting, or automated paid ad-spend boosting.</li></ul>',21)])])}const u=t(r,[["render",i]]);export{h as __pageData,u as default};
